RemappingAction::RemappingAction() : tag_(Tag::kAcceleratorAction) {
  data_.accelerator_action = ::ash::AcceleratorAction();
}

RemappingAction::~RemappingAction() {
  DestroyActive();
}


void RemappingAction::set_accelerator_action(
    ::ash::AcceleratorAction accelerator_action) {
  if (tag_ != Tag::kAcceleratorAction) {
    DestroyActive();
    tag_ = Tag::kAcceleratorAction;
  }
  data_.accelerator_action = accelerator_action;
}
void RemappingAction::set_key_event(
    KeyEventPtr key_event) {
  if (tag_ == Tag::kKeyEvent) {
    *(data_.key_event) = std::move(key_event);
  } else {
    DestroyActive();
    tag_ = Tag::kKeyEvent;
    data_.key_event = new KeyEventPtr(
        std::move(key_event));
  }
}
